x;bottom:12px;width:32px;height:32px;border-radius:10px;display:grid;place-items:center;color:#fff;background:rgba(2,11,18,.68);backdrop-filter:blur(8px);opacity:0;transform:translateY(4px);transition:opacity .2s,transform .2s;pointer-events:none}.photo:hover:after{opacity:1;transform:translateY(0)}.photo i{font-size:42px;color:#4fd5ef}.body{padding:19px}.body h2{font-size:19px;margin:0}.role{margin:7px 0 0;color:#5dc7df;font-size:11px;font-weight:800}.bio{margin:13px 0;color:#89a8b2;font-size:10px;line-height:1.7;min-height:32px}.contact-list{display:grid;gap:7px;padding:13px 0;border-top:1px solid rgba(86,210,238,.09);border-bottom:1px solid rgba(86,210,238,.09)}.contact{display:flex;align-items:center;gap:8px;color:#9db7c0;text-decoration:none;font-size:10px;min-width:0}.contact i{width:24px;height:24px;display:grid;place-items:center;border-radius:8px;background:rgba(67,209,240,.06);color:#58cee8;flex:0 0 24px}.contact span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.actions{display:grid;grid-template-columns:1fr 1fr;gap:7px;margin-top:12px}.action{display:flex;align-items:center;justify-content:center;gap:7px;padding:10px 8px;border-radius:10px;text-decoration:none;font-size:9px;font-weight:800;border:1px solid var(--line);color:#b9d8df;background:rgba(67,194,229,.035)}.action.primary{background:linear-gradient(135deg,rgba(45,177,207,.9),rgba(23,117,141,.9));border-color:transparent;color:#fff}.empty{border:1px dashed var(--line);border-radius:18px;padding:55px 20px;text-align:center;color:var(--muted);grid-column:1/-1}.empty i{font-size:35px;color:#4aa9bd;margin-bottom:12px}.footer{border-top:1px solid var(--line);padding:28px 0 45px;color:#66838e;font-size:10px}.lightbox{position:fixed;inset:0;z-index:100;background:rgba(0,6,10,.92);backdrop-filter:blur(14px);display:none;align-items:center;justify-content:center;padding:24px}.lightbox.open{display:flex}.lightbox-content{position:relative;max-width:min(96vw,1100px);max-height:94vh;display:flex;align-items:center;justify-content:center}.lightbox img{display:block;max-width:96vw;max-height:94vh;width:auto;height:auto;object-fit:contain;border-radius:12px;box-shadow:0 25px 80px rgba(0,0,0,.55)}.lightbox-close{position:fixed;top:18px;right:18px;width:42px;height:42px;border:1px solid rgba(255,255,255,.18);border-radius:12px;background:rgba(2,11,18,.75);color:#fff;display:grid;place-items:center;font-size:18px;cursor:pointer}.lightbox-close:hover{background:rgba(67,209,240,.18);border-color:rgba(86,210,238,.4)}.lightbox-hint{position:fixed;left:50%;bottom:18px;transform:translateX(-50%);color:#9db7c0;font-size:10px;background:rgba(2,11,18,.65);padding:8px 12px;border-radius:9px;border:1px solid rgba(86,210,238,.12);pointer-events:none}@media(max-width:850px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:560px){.shell{width:calc(100% - 24px)}main{padding:40px 0}.grid{grid-template-columns:1fr}.back{font-size:10px}.brand strong{font-size:13px}.actions{grid-template-columns:1fr 1fr}.photo:after{opacity:1;transform:none}.lightbox{padding:14px}.lightbox img{max-width:94vw;max-height:90vh}.lightbox-close{top:12px;right:12px}}
</style></head><body><header class="header"><div class="shell nav"><a class="brand" href="{{ route('home') }}">@if($logo)<img src="{{ asset('storage/'.$logo) }}" alt="{{ $name }}">@endif<strong>{{ $name }}</strong></a><a class="back" href="{{ route('home') }}"><i class="fa-solid fa-arrow-left"></i> Back to website</a></div></header><main class="shell"><section class="hero"><span class="eyebrow">Leadership &amp; Management</span><h1>Management Team</h1><p>Meet the people responsible for guiding {{ $name }}. Use the contact actions on each profile to call, email, view the official visiting card, or save the complete contact directly to your phone.</p></section><section class="grid">@forelse($members as $member)<article class="card"><div class="photo" @if($member->image_path) data-image="{{ asset('storage/'.$member->image_path) }}" data-name="{{ $member->title }}" role="button" tabindex="0" aria-label="View full photo of {{ $member->title }}" @endif>@if($member->image_path)<img src="{{ asset('storage/'.$member->image_path) }}" alt="{{ $member->title }}" loading="lazy">@else<i class="fa-solid fa-user-tie" aria-hidden="true"></i>@endif</div><div class="body"><h2>{{ $member->title }}</h2><div class="role">{{ $member->designation ?: $member->excerpt }}</div>@if($member->content)<div class="bio">{!! nl2br(e($member->content)) !!}</div>@endif<div class="contact-list"><a class="contact" href="tel:{{ preg_replace('/[^0-9+]/','',$member->phone) }}"><i class="fa-solid fa-phone"></i><span>{{ $member->phone }}</span></a>@if($member->email)<a class="contact" href="mailto:{{ $member->email }}"><i class="fa-solid fa-envelope"></i><span>{{ $member->email }}</span></a>@endif</div><div class="actions"><a class="action primary" href="{{ route('management.vcard',$member) }}"><i class="fa-solid fa-user-plus"></i> Add to Contacts</a>@if($member->visiting_card_path)<a class="action" href="{{ asset('storage/'.$member->visiting_card_path) }}" target="_blank" rel="noopener"><i class="fa-regular fa-address-card"></i> Visiting Card</a>@else<a class="action" href="tel:{{ preg_replace('/[^0-9+]/','',$member->phone) }}"><i class="fa-solid fa-phone"></i> Call</a>@endif</div></div></article>@empty<div class="empty"><i class="fa-solid fa-people-group" aria-hidden="true"></i><div>No management profiles have been published yet.</div></div>@endforelse</section></main><div class="lightbox" id="photoLightbox" aria-hidden="true"><button class="lightbox-close" type="button" id="lightboxClose" aria-label="Close full photo"><i class="fa-solid fa-xmark"></i></button><div class="lightbox-content"><img id="lightboxImage" src="" alt=""></div><div class="lightbox-hint">Tap outside or press Esc to close</div></div><footer class="footer"><div class="shell">{{ $name }} · Management</div></footer><script>(function(){const box=document.getElementById('photoLightbox'),image=document.getElementById('lightboxImage'),close=document.getElementById('lightboxClose');function openPhoto(photo){const src=photo.getAttribute('data-image');if(!src)return;image.src=src;image.alt=photo.getAttribute('data-name')||'Management photo';box.classList.add('open');box.setAttribute('aria-hidden','false');document.body.style.overflow='hidden'}function closePhoto(){box.classList.remove('open');box.setAttribute('aria-hidden','true');image.src='';document.body.style.overflow=''}document.querySelectorAll('.photo[data-image]').forEach(photo=>{photo.addEventListener('click',function(){openPhoto(photo)});photo.addEventListener('keydown',function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();openPhoto(photo)}})});close.addEventListener('click',closePhoto);box.addEventListener('click',function(e){if(e.target===box)closePhoto()});document.addEventListener('keydown',function(e){if(e.key==='Escape'&&box.classList.contains('open'))closePhoto()})})();</script></body></html>
